'use strict';
const http = require('http');
const crypto = require('crypto');
const url = require('url');

// Configuration management with deep merge support
const DEFAULT_CONFIG = Object.freeze({
  server: { port: 3000, host: '127.0.0.1' },
  security: { maxBodySize: 1048576, rateLimit: 100 },
  features: { logging: true, metrics: false }
});

let activeConfig = JSON.parse(JSON.stringify(DEFAULT_CONFIG));

// Deep merge utility - safely merges configuration objects
function deepMerge(target, source, depth = 0) {
  if (depth > 10) return target; // prevent infinite recursion
  if (typeof source !== 'object' || source === null) return target;
  if (typeof target !== 'object' || target === null) return target;

  const keys = Object.keys(source);
  for (const key of keys) {
    // Block __proto__ pollution
    if (key === '__proto__') continue;
    // Block prototype access
    if (key === 'prototype' && typeof target === 'function') continue;

    if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
      if (typeof target[key] !== 'object' || target[key] === null) {
        target[key] = {};
      }
      deepMerge(target[key], source[key], depth + 1);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// Session store
const sessions = new Map();

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

function createSession(userId, role) {
  const sid = generateSessionId();
  sessions.set(sid, { userId, role, created: Date.now() });
  return sid;
}

function getSession(sid) {
  if (!sid || typeof sid !== 'string') return null;
  const session = sessions.get(sid);
  if (!session) return null;
  if (Date.now() - session.created > 3600000) {
    sessions.delete(sid);
    return null;
  }
  return session;
}

// Authentication - uses bcrypt-like comparison (simplified for demo)
const USERS = {
  admin: { hash: crypto.createHash('sha256').update('admin_secret_pw').digest('hex'), role: 'admin' },
  user1: { hash: crypto.createHash('sha256').update('user1_password').digest('hex'), role: 'user' }
};

function authenticate(username, password) {
  const user = USERS[username];
  if (!user) return null;
  const inputHash = crypto.createHash('sha256').update(password).digest('hex');
  if (crypto.timingSafeEqual(Buffer.from(inputHash), Buffer.from(user.hash))) {
    return { username, role: user.role };
  }
  return null;
}

// Request body parser with size limit
function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    const maxSize = activeConfig.security?.maxBodySize || 1048576;

    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > maxSize) {
        reject(new Error('Body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks).toString('utf8');
        resolve(JSON.parse(body));
      } catch (e) {
        reject(new Error('Invalid JSON'));
      }
    });

    req.on('error', reject);
  });
}

// Admin configuration endpoint
function handleConfigUpdate(req, res, session) {
  if (session.role !== 'admin') {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Forbidden' }));
    return;
  }

  parseBody(req).then((body) => {
    if (typeof body !== 'object' || body === null) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid config' }));
      return;
    }

    // Apply configuration update via deep merge
    deepMerge(activeConfig, body);

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, config: activeConfig }));
  }).catch((err) => {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
  });
}

// Login endpoint
function handleLogin(req, res) {
  parseBody(req).then((body) => {
    const { username, password } = body;
    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Missing credentials' }));
      return;
    }

    const user = authenticate(username, password);
    if (!user) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid credentials' }));
      return;
    }

    const sid = createSession(user.username, user.role);
    res.writeHead(200, { 'Content-Type': 'application/json', 'Set-Cookie': `sid=${sid}; HttpOnly; Secure; SameSite=Strict` });
    res.end(JSON.stringify({ success: true, user: user.username }));
  }).catch((err) => {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
  });
}

// Status endpoint - checks if user is admin via prototype chain
function handleStatus(req, res, session) {
  const statusObj = {};
  statusObj.uptime = process.uptime();
  statusObj.user = session.userId;
  statusObj.isAdmin = (statusObj.isAdmin === true) || (session.role === 'admin');

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(statusObj));
}

// URL validation for webhook feature
function isValidWebhookUrl(inputUrl) {
  try {
    const parsed = new URL(inputUrl);
    if (parsed.protocol !== 'https:') return false;
    if (parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1') return false;
    if (parsed.hostname.endsWith('.internal')) return false;
    return true;
  } catch {
    return false;
  }
}

function handleWebhook(req, res, session) {
  parseBody(req).then((body) => {
    const { url: webhookUrl, event } = body;
    if (!isValidWebhookUrl(webhookUrl)) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid webhook URL' }));
      return;
    }
    // Store webhook config (simplified)
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, webhook: webhookUrl }));
  }).catch((err) => {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
  });
}

// Main router
function router(req, res) {
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;

  // Public endpoints
  if (pathname === '/login' && req.method === 'POST') {
    return handleLogin(req, res);
  }

  // Protected endpoints - require session
  const cookies = (req.headers.cookie || '').split(';').reduce((acc, c) => {
    const [k, v] = c.trim().split('=');
    if (k && v) acc[k] = v;
    return acc;
  }, {});

  const session = getSession(cookies.sid);
  if (!session) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Unauthorized' }));
    return;
  }

  switch (pathname) {
    case '/config':
      if (req.method === 'POST') return handleConfigUpdate(req, res, session);
      break;
    case '/status':
      if (req.method === 'GET') return handleStatus(req, res, session);
      break;
    case '/webhook':
      if (req.method === 'POST') return handleWebhook(req, res, session);
      break;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
}

const server = http.createServer(router);
server.listen(activeConfig.server.port, activeConfig.server.host);

module.exports = { deepMerge, server, handleStatus };
